server <- function(input, output, session) {
  # summary ----
  output$summary_cdm_name <- shinyTree::renderTree(summaryCdmName(data))
  output$summary_packages <- shinyTree::renderTree(summaryPackages(data))
  output$summary_min_cell_count <- shinyTree::renderTree(summaryMinCellCount(data))
  output$summary_panels <- shinyTree::renderTree(summaryPanels(data))
  # download raw data -----
  output$download_raw <- shiny::downloadHandler(
    filename = "results.csv",
    content = function(file) {
      data |>
        omopgenerics::bind() |>
        omopgenerics::exportSummarisedResult(
          fileName = file, logFile = NULL, logSqlPath = NULL
        )
    }
  )
  # update buttons ----
  updateButtons <- shiny::reactiveValues(
    summarise_omop_snapshot = FALSE,
    summarise_observation_period = FALSE,
    summarise_cohort_attrition = FALSE,
    summarise_characteristics = FALSE,
    summarise_log_file = FALSE,
    summarise_table = FALSE,
    vaccinated_table = FALSE,
    summarise_coverage = FALSE
  )


  # summarise_omop_snapshot -----
  ## update message if filter is changed
  shiny::observe({
    updateButtons$summarise_omop_snapshot <- TRUE
  }) |>
    shiny::bindEvent(
      input$summarise_omop_snapshot_cdm_name,
      input$summarise_omop_snapshot_variable_name,
      ignoreInit = TRUE
    )
  shiny::observeEvent(updateButtons$summarise_omop_snapshot, {
    if (updateButtons$summarise_omop_snapshot == TRUE) {
      output$update_message_summarise_omop_snapshot <- shiny::renderUI(updateMessage) # defined in functions.R
    } else {
      output$update_message_summarise_omop_snapshot <- shiny::renderUI(NULL)
    }
  })
  shiny::observeEvent(input$update_summarise_omop_snapshot, {
    updateButtons$summarise_omop_snapshot <- FALSE
  })

  ## get summarise_omop_snapshot data
  getSummariseOmopSnapshotData <- shiny::eventReactive(input$update_summarise_omop_snapshot, {
    data[["summarise_omop_snapshot"]] |>
      dplyr::filter(
        .data$cdm_name %in% input$summarise_omop_snapshot_cdm_name,
        .data$variable_name %in% input$summarise_omop_snapshot_variable_name
      )
  })
  getSummariseOmopSnapshotTable <- shiny::reactive({
    getSummariseOmopSnapshotData() |>
      OmopSketch::tableOmopSnapshot(
        header = input$summarise_omop_snapshot_table_header,
        groupColumn = input$summarise_omop_snapshot_table_group_column,
        hide = input$summarise_omop_snapshot_table_hide
      )
  })
  output$summarise_omop_snapshot_table <- gt::render_gt({
    getSummariseOmopSnapshotTable()
  })
  output$summarise_omop_snapshot_table_download <- shiny::downloadHandler(
    filename = paste0("table_snapshot.", input$summarise_omop_snapshot_table_format),
    content = function(file) {
      gt::gtsave(getSummariseOmopSnapshotTable(), file)
    }
  )

  # summarise_observation_period -----
  ## update message if filter is changed
  shiny::observe({
    updateButtons$summarise_observation_period <- TRUE
  }) |>
    shiny::bindEvent(
      input$summarise_observation_period_cdm_name,
      input$summarise_observation_period_observation_period_ordinal,
      input$summarise_observation_period_variable_name,
      input$summarise_observation_period_estimate_name,
      ignoreInit = TRUE
    )
  shiny::observeEvent(updateButtons$summarise_observation_period, {
    if (updateButtons$summarise_observation_period == TRUE) {
      output$update_message_summarise_observation_period <- shiny::renderUI(updateMessage) # defined in functions.R
    } else {
      output$update_message_summarise_observation_period <- shiny::renderUI(NULL)
    }
  })
  shiny::observeEvent(input$update_summarise_observation_period, {
    updateButtons$summarise_observation_period <- FALSE
  })

  ## get summarise_observation_period data
  getSummariseObservationPeriodData <- shiny::eventReactive(input$update_summarise_observation_period, {
    data[["summarise_observation_period"]] |>
      dplyr::filter(
        .data$cdm_name %in% input$summarise_observation_period_cdm_name,
        .data$variable_name %in% input$summarise_observation_period_variable_name,
        .data$estimate_name %in% input$summarise_observation_period_estimate_name
      ) |>
      omopgenerics::filterGroup(.data$observation_period_ordinal %in% input$summarise_observation_period_observation_period_ordinal)
  })
  getSummariseObservationPeriodTable <- shiny::reactive({
    getSummariseObservationPeriodData() |>
      OmopSketch::tableObservationPeriod(
        header = input$summarise_observation_period_table_header,
        groupColumn = input$summarise_observation_period_table_group_column,
        hide = input$summarise_observation_period_table_hide
      )
  })
  output$summarise_observation_period_table <- gt::render_gt({
    getSummariseObservationPeriodTable()
  })
  output$summarise_observation_period_table_download <- shiny::downloadHandler(
    filename = paste0("table_obsevation_period.", input$summarise_observation_period_table_format),
    content = function(file) {
      gt::gtsave(getSummariseObservationPeriodTable(), file)
    }
  )
  getSummariseObservationPeriodPlot <- shiny::reactive({
    getSummariseObservationPeriodData() |>
      OmopSketch::plotObservationPeriod(
        variableName = input$summarise_observation_period_plot_variable,
        plotType = input$summarise_observation_period_plot_plot_type,
        facet = input$summarise_observation_period_plot_facet,
        colour = input$summarise_observation_period_plot_colour
      )
  })
  output$summarise_observation_period_plot <- shiny::renderUI({
    x <- getSummariseObservationPeriodPlot()
    renderInteractivePlot(x, input$summarise_observation_period_plot_interactive)
  })
  output$summarise_observation_period_plot_download <- shiny::downloadHandler(
    filename = "plot_observation_period.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSummariseObservationPeriodPlot(),
        width = as.numeric(input$summarise_observation_period_plot_width),
        height = as.numeric(input$summarise_observation_period_plot_height),
        units = input$summarise_observation_period_plot_units,
        dpi = as.numeric(input$summarise_observation_period_plot_dpi)
      )
    }
  )

  # summarise_cohort_attrition -----
  ## update message if filter is changed
  shiny::observe({
    updateButtons$summarise_cohort_attrition <- TRUE
  }) |>
    shiny::bindEvent(
      input$summarise_cohort_attrition_cdm_name,
      input$summarise_cohort_attrition_cohort_name,
      input$summarise_cohort_attrition_table_name,
      input$summarise_cohort_attrition_variable_name,
      ignoreInit = TRUE
    )
  shiny::observeEvent(updateButtons$summarise_cohort_attrition, {
    if (updateButtons$summarise_cohort_attrition == TRUE) {
      output$update_message_summarise_cohort_attrition <- shiny::renderUI(updateMessage) # defined in functions.R
    } else {
      output$update_message_summarise_cohort_attrition <- shiny::renderUI(NULL)
    }
  })
  shiny::observeEvent(input$update_summarise_cohort_attrition, {
    updateButtons$summarise_cohort_attrition <- FALSE
  })

  ## get summarise_cohort_attrition data
    getSummariseCohortAttritionData <- shiny::eventReactive(input$update_summarise_cohort_attrition, {
      data[["summarise_cohort_attrition"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_cohort_attrition_cdm_name,
          .data$variable_name %in% input$summarise_cohort_attrition_variable_name
        ) |>
        dplyr::mutate(
          group_level = pretty_labels(group_level),
          group_level = factor(
            group_level,
            levels = c("Covid vaccine", "Autumn 2023", "Spring 2024", "Autumn 2024", "Spring 2025")
          )) |>
        print()|>
        omopgenerics::filterGroup(.data$cohort_name %in% input$summarise_cohort_attrition_cohort_name) |>
        omopgenerics::filterSettings(.data$table_name %in% input$summarise_cohort_attrition_table_name) 
       
    })
  getSummariseCohortAttritionTable <- shiny::reactive({
    getSummariseCohortAttritionData() |>
      dplyr::arrange(.data$group_level) |>
      CohortCharacteristics::tableCohortAttrition(
        header = input$summarise_cohort_attrition_table_header,
        groupColumn = input$summarise_cohort_attrition_table_group_column,
        hide = input$summarise_cohort_attrition_table_hide
      )
  })
  output$summarise_cohort_attrition_table <- gt::render_gt({
    getSummariseCohortAttritionTable()
  })
  output$summarise_cohort_attrition_table_download <- shiny::downloadHandler(
    filename = paste0("table_attrition.", input$summarise_cohort_attrition_table_format),
    content = function(file) {
      gt::gtsave(getSummariseCohortAttritionTable(), file)
    }
  )
  getSummariseCohortAttritionDiagram <- shiny::reactive({
    getSummariseCohortAttritionData() |>
      dplyr::arrange(.data$group_level) |>
      CohortCharacteristics::plotCohortAttrition(
        show = input$summarise_cohort_attrition_diagram_show
      )
  })
  output$summarise_cohort_attrition_diagram <- DiagrammeR::renderGrViz({
    getSummariseCohortAttritionDiagram()
  })
  output$summarise_cohort_attrition_diagram_download <- shiny::downloadHandler(
    filename = "attrition_diagram.png",
    content = function(file) {
      svg <- DiagrammeRsvg::export_svg(getSummariseCohortAttritionDiagram())
      rsvg::rsvg_png(charToRaw(svg), file, width = input$summarise_cohort_attrition_diagram_width)
    }
  )

  # summarise_characteristics -----
  ## update message if filter is changed
  shiny::observe({
    updateButtons$summarise_characteristics <- TRUE
  }) |>
    shiny::bindEvent(
      input$summarise_characteristics_cdm_name,
      input$summarise_characteristics_cohort_name,
      input$summarise_characteristics_table_name,
      input$summarise_characteristics_variable_name,
      input$summarise_characteristics_estimate_name,
      ignoreInit = TRUE
    )
  shiny::observeEvent(updateButtons$summarise_characteristics, {
    if (updateButtons$summarise_characteristics == TRUE) {
      output$update_message_summarise_characteristics <- shiny::renderUI(updateMessage) # defined in functions.R
    } else {
      output$update_message_summarise_characteristics <- shiny::renderUI(NULL)
    }
  })
  shiny::observeEvent(input$update_summarise_characteristics, {
    updateButtons$summarise_characteristics <- FALSE
  })

  ## get summarise_characteristics data
  getSummariseCharacteristicsData <- shiny::eventReactive(input$update_summarise_characteristics, {
    data[["summarise_characteristics"]] |>
      dplyr::filter(
        .data$cdm_name %in% input$summarise_characteristics_cdm_name,
        .data$variable_name %in% input$summarise_characteristics_variable_name,
        .data$estimate_name %in% input$summarise_characteristics_estimate_name
      ) |>
      print()|>
      dplyr::mutate(
        variable_name = case_when(variable_name == "Imd" ~ "TDI",
                                  TRUE ~ variable_name),
        group_level = pretty_labels(group_level)) |>
      omopgenerics::filterGroup(.data$cohort_name %in% input$summarise_characteristics_cohort_name) |>
      omopgenerics::filterSettings(.data$table_name %in% input$summarise_characteristics_table_name)
  })
  getSummariseCharacteristicsTable <- shiny::reactive({
    getSummariseCharacteristicsData() |>
      CohortCharacteristics::tableCharacteristics(
        header = input$summarise_characteristics_table_header,
        groupColumn = input$summarise_characteristics_table_group_column,
        hide = input$summarise_characteristics_table_hide
      )
  })
  output$summarise_characteristics_table <- gt::render_gt({
    getSummariseCharacteristicsTable()
  })
  output$summarise_characteristics_table_download <- shiny::downloadHandler(
    filename = paste0("table_characteristics.", input$summarise_characteristics_table_format),
    content = function(file) {
      gt::gtsave(getSummariseCharacteristicsTable(), file)
    }
  )
  getSummariseCharacteristicsPlot <- shiny::reactive({
    getSummariseCharacteristicsData() |>
      CohortCharacteristics::plotCharacteristics(
        plotType = input$summarise_characteristics_plot_plot_type,
        facet = input$summarise_characteristics_plot_facet,
        colour = input$summarise_characteristics_plot_colour
      )
  })
  
  output$summarise_characteristics_plot <- shiny::renderUI({
    x <- getSummariseCharacteristicsPlot()
    renderInteractivePlot(x, input$summarise_characteristics_plot_interactive)
  })
  output$summarise_characteristics_plot_download <- shiny::downloadHandler(
    filename = "plot_characteristics.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSummariseCharacteristicsPlot(),
        width = as.numeric(input$summarise_characteristics_plot_width),
        height = as.numeric(input$summarise_characteristics_plot_height),
        units = input$summarise_characteristics_plot_units,
        dpi = as.numeric(input$summarise_characteristics_plot_dpi)
      )
    }
  )

  # Vaccination Chronology -----
  ## vaccinated eligibles in campaign, imported by me 
  library(dplyr)
  library(readr)
  library(ggplot2)
  
  plot_dose <- read.csv(here::here("plot_dose.csv"))
  
  plot_dose <- plot_dose |>
    mutate(cohort_start_date = as.Date(cohort_start_date))
  
  plot_dosef <- plot_dose |> filter(n_dose_day>5L)
  
  campaigns <- tibble::tibble(
    vaccination_campaign = c("a_2023","s_2024","a_2024","s_2025","a_2025"),
    start    = as.Date(c("2023-10-02","2024-04-15","2024-10-03","2025-04-01","2025-10-01")), 
    end      = as.Date(c("2024-01-31","2024-06-30","2025-01-31","2025-06-17","2026-01-31"))
  ) |>
    mutate(
      split = case_when(
        vaccination_campaign == "a_2023" ~ end - 47,
        vaccination_campaign == "a_2024" ~ end - 42,
        vaccination_campaign == "a_2025" ~ end - 45,
        TRUE ~ as.Date(NA)
      )
    )|>
    filter(!vaccination_campaign=="a_2025")
  
  bg_full <- campaigns |>
    transmute(
      vaccination_campaign,
      xmin = start,
      xmax = end,
      ymin = -Inf,
      ymax = Inf
    )
  
  bg_tail <- campaigns |>
    filter(!is.na(split)) |>
    transmute(
      vaccination_campaign,
      xmin = split,
      xmax = end,
      ymin = -Inf,
      ymax = Inf
    )
  
  plot_dosef <- plot_dosef |>
    mutate(
      Dose = factor(
        paste(dose, "dose"),
        levels = paste(1:13, "dose"),
        ordered = TRUE
      )
    )|>
    collect(name=plot_dosef) 
  
  y_max <- max(plot_dosef$n_dose_day, na.rm = TRUE) * 1.05
  
  bg_full <- campaigns |>
    transmute(vaccination_campaign, xmin = start, xmax = end, ymin = 0, ymax = y_max)
  
  bg_tail <- campaigns |>
    filter(!is.na(split)) |>
    transmute(vaccination_campaign, xmin = split, xmax = end, ymin = 0, ymax = y_max)
  graph <- ggplot(plot_dosef|>filter(!vaccination_campaign == "a_2025"), aes(x = cohort_start_date, y = n_dose_day, fill = Dose)) +
    geom_rect(
      data = bg_full,
      aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
      inherit.aes = FALSE,
      fill = "grey90",
      alpha = 0.5
    ) +
    geom_rect(
      data = bg_tail,
      aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
      inherit.aes = FALSE,
      fill = "grey75",
      alpha = 0.6
    ) +
    geom_col(position = "stack", width = 1) +
    scale_x_date(date_breaks = "3 month", 
                 limits = c(as.Date("2020-12-01"), NA),
                 date_labels = "%Y-%m", expand = c(0, 0)) +
    theme_bw() +
    theme(legend.position = "bottom", axis.text.x = element_text(angle = 45, hjust = 1)) +
    labs(x = "Date", y = "Number of vaccine recipients")
  print(graph) 

  ac <- plot_dosef |> group_by(Dose) |>
    mutate(
      acummulative_vaccination = cumsum(n_dose_day)
    ) |>
    ungroup() 
  y_max <- max(ac$acummulative_vaccination, na.rm = TRUE) * 1.05
  
  bg_full <- campaigns |>
    transmute(vaccination_campaign, xmin = start, xmax = end, ymin = 0, ymax = y_max)
  
  bg_tail <- campaigns |>
    filter(!is.na(split)) |>
    transmute(vaccination_campaign, xmin = split, xmax = end, ymin = 0, ymax = y_max)
  plot0 <- ggplot(ac, aes(x = cohort_start_date, y = acummulative_vaccination, colour = Dose)) +
    geom_rect(
      data = bg_full,
      aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
      inherit.aes = FALSE,
      fill = "grey90",
      alpha = 0.5
    ) +
    geom_rect(
      data = bg_tail,
      aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
      inherit.aes = FALSE,
      fill = "grey75",
      alpha = 0.6
    ) +
    geom_line(linewidth = 1) +
    scale_x_date(
      date_breaks = "3 month",
      limits = c(as.Date("2020-12-01"), NA),
      date_labels = "%Y-%m",
      expand = c(0, 0)
    ) +
    scale_y_continuous(
      expand = expansion(mult = c(0, 0.05)),
      breaks = scales::pretty_breaks(n = 5),
      labels = scales::label_number(big.mark = ",")
    ) +
    theme_bw() +
    theme(
      legend.position = "bottom",
      axis.text.x = element_text(angle = 45, hjust = 1),
      axis.text.y = element_text(margin = margin(r = 6)),
      axis.title.y = element_text(margin = margin(r = 10)),
      plot.margin = margin(10, 30, 10, 20)
    ) +
    guides(colour = guide_legend(nrow = 2)) +
    labs(
      x = "Date",
      y = "Cumulative number of vaccine recipients",
      colour = "Dose:"
    )
  
  library(dplyr)
  library(readr)
  library(ggplot2)
  
  plot_dose <- read.csv(here::here("plot_dosee.csv"))
  
  plot_dose <- plot_dose |>
    mutate(cohort_start_date = as.Date(cohort_start_date))
  
  plot_dosef <- plot_dose |> filter(n_dose_day>5L)
  
  campaigns <- tibble::tibble(
    vaccination_campaign = c("a_2023","s_2024","a_2024","s_2025","a_2025"),
    start    = as.Date(c("2023-10-02","2024-04-15","2024-10-03","2025-04-01","2025-10-01")), 
    end      = as.Date(c("2024-01-31","2024-06-30","2025-01-31","2025-06-17","2026-01-31"))
  ) |>
    mutate(
      split = case_when(
        vaccination_campaign == "a_2023" ~ end - 47,
        vaccination_campaign == "a_2024" ~ end - 42,
        vaccination_campaign == "a_2025" ~ end - 45,
        TRUE ~ as.Date(NA)
      )
    )
  
  plot_dosef <- plot_dosef |>
    mutate(
      Dose = factor(
        paste(dose, "dose"),
        levels = paste(3: 12, "dose"),
        ordered = TRUE
      )
    )|>
    collect(name=plot_dosef) 
  
  plot_with_campaign <- plot_dosef |>
    filter(vaccination_campaign!="None" & !is.na(vaccination_campaign))
  
  plot_with_campaign <- plot_with_campaign |>
    left_join(campaigns, by = "vaccination_campaign") |>
    mutate(day_campaign = cohort_start_date - start) |>
    mutate(vaccination_campaign = factor(vaccination_campaign,
                                         levels = c("a_2023", "s_2024", "a_2024", "s_2025"), 
                                         labels = c("Autumn 2023", "Spring 2024",
                                                    "Autumn 2024", "Spring 2025"),
                                         ordered = TRUE))
  
  campaign_bands <- campaigns |>
    mutate(
      x_end = as.numeric(end - start),
      x_split = case_when(
        vaccination_campaign == "a_2023" ~ x_end - 47,
        vaccination_campaign == "a_2024" ~ x_end - 42,
        vaccination_campaign == "a_2025" ~ x_end - 45,
        TRUE ~ NA_real_
      )
    )|>
    mutate(vaccination_campaign = factor(vaccination_campaign,
                                         levels = c("a_2023", "s_2024", "a_2024", "s_2025"), 
                                         labels = c("Autumn 2023", "Spring 2024",
                                                    "Autumn 2024", "Spring 2025"),
                                         ordered = TRUE)) |>
    filter(!is.na(vaccination_campaign))
  
  bg_full <- campaign_bands |>
    transmute( #mutate(.keep = "none")
      vaccination_campaign,
      xmin = 0,
      xmax = x_end,
      ymin = -Inf,
      ymax = Inf
    )
  
  bg_tail <- campaign_bands |>
    filter(!is.na(x_split)) |>
    transmute(
      vaccination_campaign,
      xmin = x_split,
      xmax = x_end,
      ymin = -Inf,
      ymax = Inf
    )
  
  graph2 <- ggplot(
    plot_with_campaign |>
      filter(!is.na(vaccination_campaign)) |>
      mutate(day_campaign = as.numeric(day_campaign)),
    aes(x = day_campaign, y = n_dose_day, fill = Dose)
  ) +
    geom_rect(
      data = bg_full,
      aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
      inherit.aes = FALSE,
      fill = "grey90",
      alpha = 0.5
    ) +
    geom_rect(
      data = bg_tail,
      aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
      inherit.aes = FALSE,
      fill = "grey75",
      alpha = 0.6
    ) +
    geom_col() +
    facet_grid(vaccination_campaign ~ ., scales = "free_x", space = "free_x") +
    scale_x_continuous(expand = c(0, 0)) +
    theme_bw() +
    theme(axis.title = element_text(size = 20),      # x and y axis titles
          axis.text = element_text(size = 14),       # axis tick labels
          legend.title = element_text(size = 16),    # legend title
          legend.text = element_text(size = 14),     # legend labels
          plot.title = element_text(size = 18),      # plot title
          strip.text = element_text(size = 14)       # facet labels
    ) +
    labs(x = "Days since campaign start", y = "Number of vaccine recipients")
  
  print(graph2)
  
  output$eligibles_plot1 <- shiny::renderUI({
    x <- graph
    renderInteractivePlot(x, TRUE)
  })
  
  output$eligibles_plot <- shiny::renderUI({
    x <- graph2
    renderInteractivePlot(x, TRUE)
  })
  
  output$cumulative_eligibles_plot <- shiny::renderUI({
    x <- plot0
    renderInteractivePlot(x, TRUE)
  })
  
  output$summarise_choronology_plot_download1 <- shiny::downloadHandler(
    filename = function() {
      "vaccinated_all1.png"
    },
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = graph,
        width = 15,
        height = 15,
        units = "cm",
        dpi = 300
      )
    }
  )
  
  output$summarise_choronology_plot_download <- shiny::downloadHandler(
    filename = function() {
      "EligiblesVaccinatedInCampaign1.png"
    },
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = graph2,
        width = 15,
        height = 15,
        units = "cm",
        dpi = 300
      )
