  # summarise_log_file -----
  ## update message if filter is changed
  shiny::observe({
    updateButtons$summarise_log_file <- TRUE
  }) |>
    shiny::bindEvent(
      input$summarise_log_file_cdm_name,
      input$summarise_log_file_variable_name,
      ignoreInit = TRUE
    )
  shiny::observeEvent(updateButtons$summarise_log_file, {
    if (updateButtons$summarise_log_file == TRUE) {
      output$update_message_summarise_log_file <- shiny::renderUI(updateMessage) # defined in functions.R
    } else {
      output$update_message_summarise_log_file <- shiny::renderUI(NULL)
    }
  })
  shiny::observeEvent(input$update_summarise_log_file, {
    updateButtons$summarise_log_file <- FALSE
  })
  
  # Linear plots -----
  ## Linear plots imported by me 
  output$linear_regression <- shiny::renderUI({
    if (isTRUE(input$models_combined)) {
      img <- "lr_all.png"
    } else {
      img <- "lr_sep.png"
    }
    shiny::tags$img(src = img, width = "80%")
  })
  
  output$summarise_linerplot_plot_download <- shiny::downloadHandler(
    filename = function() {
      if (isTRUE(input$models_combined)) {
        "linear_regression_combined.png"
      } else {
        "linear_regression_sequential.png"
      }
    },
    content = function(file) {
      if (isTRUE(input$models_combined)) {
        file.copy("www/lr_all.png", file)
      } else {
        file.copy("www/lr_sep.png", file)
      }
    }
  )
  
  ## get summarise_log_file data
  getSummariseLogFileData <- shiny::eventReactive(input$update_summarise_log_file, {
    data[["summarise_log_file"]] |>
      dplyr::filter(
        .data$cdm_name %in% input$summarise_log_file_cdm_name,
        .data$variable_name %in% input$summarise_log_file_variable_name
      )
  })
  getSummariseLogFileTable <- shiny::reactive({
    getSummariseLogFileData() |>
      dplyr::filter(.data$estimate_name == "date_time") |>
      visOmopResults::visOmopTable(
        header = "cdm_name",
        hide = c("variable_level", "estimate_name")
      )
  })
  output$summarise_log_file_table <- gt::render_gt({
    getSummariseLogFileTable()
  })
  output$summarise_log_file_table_download <- shiny::downloadHandler(
    filename = paste0("table_log.", input$summarise_log_file_table_format),
    content = function(file) {
      gt::gtsave(getSummariseLogFileTable(), file)
    }
  )
  getSummariseLogFilePlot <- shiny::reactive({
    getSummariseLogFileData() |>
      dplyr::filter(.data$estimate_name == "elapsed_time") |>
      visOmopResults::barPlot(
        x = c("log_id", "variable_name"),
        y = "elapsed_time",
        colour = "cdm_name",
        position = input$summarise_log_file_plot_position
      )
  })
  output$summarise_log_file_plot <- shiny::renderUI({
    x <- getSummariseLogFilePlot()
    renderInteractivePlot(x, input$summarise_log_file_plot_interactive)
  })
  output$summarise_log_file_plot_download <- shiny::downloadHandler(
    filename = "plot_logs.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSummariseLogFilePlot(),
        width = as.numeric(input$summarise_log_file_plot_width),
        height = as.numeric(input$summarise_log_file_plot_height),
        units = input$summarise_log_file_plot_units,
        dpi = as.numeric(input$summarise_log_file_plot_dpi)
      )
    })
  
  # objective 3: associated factors ----
  
  models <- c(
    "fit_agr", "fit_agr_sex", "fit_agr_sex_eth", "fit_agr_sex_imd",
    "fit_agr_sex_reg", "fit_agr_sex_immuno", "fit_all"
  )
  
  plot_levels <- c(
    "Non immunosuppressed", "Immunosuppressed",
    "England", "Northern Ireland", "Scotland", "Wales",
    "Q1", "Q2", "Q3", "Q4", "Q5",
    "White", "Black", "Asian", "Missing",
    "Female", "Male",
    "<=34", "35-44", "45-54", "55-64",
    "65-74", "75-84", "85-94", ">=95"
  )
  
  var_labels <- c(
    age_group = "Age group",
    sex = "Sex",
    ethnicity = "Ethnicity",
    imd = "TDI",
    region = "Region",
    immuno = "Immunosuppression"
  )
  
  var_prefixes <- names(var_labels)
  
  make_ref_plot <- function(campaign_levels) {
    tidyr::crossing(
      tibble::tibble(
        term = c("75-84", "Female", "White", "Q3", "Scotland", "Non immunosuppressed"),
        estimate = c(1, 1, 1, 1, 1, 1),
        var_group = unname(var_labels)
      ),
      campaign = campaign_levels
    ) |>
      dplyr::mutate(
        term = factor(term, levels = plot_levels),
        var_group = factor(var_group, levels = unname(var_labels))
      )
  }
  
  getLinearRegressionData <- shiny::reactive({
    tidy_fit |>
      dplyr::filter(.data$term != "(Intercept)") |>
      dplyr::mutate(
        var_group = purrr::map_chr(.data$term, ~ {
          match <- var_prefixes[stringr::str_starts(.x, .env$var_prefixes)]
          if (length(match) == 0) NA_character_ else match[1]
        }),
        term = dplyr::if_else(
          .data$var_group != "immuno",
          stringr::str_remove(.data$term, paste0("^", .data$var_group)),
          "Immunosuppressed"
        ),
        term = dplyr::if_else(
          .data$var_group == "ethnicity",
          stringr::str_to_title(.data$term),
          .data$term
        ),
        term = factor(.data$term, levels = plot_levels),
        campaign = dplyr::case_when(
          campaign == "a_2023" ~ "Autumn 2023",
          campaign == "a_2024" ~ "Autumn 2024",
          campaign == "s_2024" ~ "Spring 2024",
          campaign == "s_2025" ~ "Spring 2025",
          TRUE ~ campaign
        ),
        campaign = factor(
          .data$campaign,
          levels = c("Autumn 2023", "Spring 2024", "Autumn 2024", "Spring 2025")
        ),
        var_group = factor(
          .data$var_group,
          levels = names(var_labels),
          labels = unname(var_labels)
        )
      ) |>
      dplyr::filter(
        (.data$model == models[[1]] & .data$var_group == unname(var_labels)[[1]]) |
          (.data$model == models[[2]] & .data$var_group == unname(var_labels)[[2]]) |
          (.data$model == models[[3]] & .data$var_group == unname(var_labels)[[3]]) |
          (.data$model == models[[4]] & .data$var_group == unname(var_labels)[[4]]) |
          (.data$model == models[[5]] & .data$var_group == unname(var_labels)[[5]]) |
          (.data$model == models[[6]] & .data$var_group == unname(var_labels)[[6]]) |
          (.data$model == models[[7]])
      )
  })
  
  getLinearRegressionPlot <- shiny::reactive({
    df <- getLinearRegressionData()
    
    ref_plot <- make_ref_plot(unique(df$campaign))
    
    if (isTRUE(input$models_combined)) {
      ggplot2::ggplot(
        df |> dplyr::filter(.data$model == "fit_all"),
        ggplot2::aes(x = estimate, y = term, colour = var_group)
      ) +
        ggplot2::geom_point() +
        ggplot2::geom_errorbar(
          ggplot2::aes(xmin = conf.low, xmax = conf.high),
          orientation = "y",
          width = 0.2
        ) +
        ggplot2::geom_point(
          data = ref_plot,
          ggplot2::aes(x = estimate, y = term, colour = var_group),
          shape = 0,
          show.legend = FALSE
        ) +
        ggplot2::facet_grid(~ campaign) +
        ggplot2::geom_vline(xintercept = 1, linetype = "dashed") +
        ggplot2::scale_x_continuous(
          trans = "log",
          limits = c(0.05, 2),
          breaks = c(0.05, 0.1, 0.25, 0.5, 1, 2)
        ) +
        ggplot2::scale_y_discrete(limits = plot_levels) +
        ggplot2::scale_colour_manual(
          values = c(
            `Age group` = "#FF0000",
            Sex = "#0000CC",
            Ethnicity = "deeppink2",
            Region = "darkorange1",
            TDI = "#009900",
            Immunosuppression = "magenta4"
            
          ),
          name = "Covariates: "
        ) +
        ggplot2::guides(
          colour = ggplot2::guide_legend(override.aes = list(shape = 16))
        ) +
        ggplot2::labs(
          x = "Odds Ratio (log scale)",
          y = ""
        ) +
        ggplot2::theme_bw() +
        ggplot2::theme(
          axis.title = element_text(size = 16),
          axis.text = element_text(size = 14),
          legend.title = element_text(size = 16),
          legend.text = element_text(size = 14),
          strip.text = element_text(size = 14),
          axis.text.x = element_text(angle = 45, hjust = 1)
        )
    } else {
      ggplot2::ggplot(
        df |> dplyr::filter(.data$model != "fit_all"),
        ggplot2::aes(x = estimate, y = term, colour = var_group)
      ) +
        ggplot2::geom_point() +
        ggplot2::geom_errorbarh(
          ggplot2::aes(xmin = conf.low, xmax = conf.high),
          height = 0.2
        ) +
        ggplot2::geom_point(
          data = ref_plot,
          ggplot2::aes(x = estimate, y = term, colour = var_group),
          shape = 0,
          show.legend = FALSE
        ) +
        ggplot2::geom_vline(xintercept = 1, linetype = "dashed") +
        ggplot2::scale_y_discrete(
          limits = function(x) intersect(plot_levels, x),
          drop = TRUE
        ) +
        ggplot2::facet_grid(
          var_group ~ campaign,
          scales = "free_y",
          space = "free_y",
          labeller = ggplot2::labeller(
            var_group = c(Immunosuppression = "I*")
          )
        ) +
        ggplot2::scale_x_continuous(
          trans = "log",
          limits = c(0.05, 2),
          breaks = c(0.05, 0.1, 0.25, 0.5, 1, 2)
        ) +
        ggplot2::scale_colour_manual(
          values = c(
            `Age group` = "#FF0000",
            Sex = "#0000CC",
            Ethnicity = "deeppink2",
            Region = "darkorange1",
            TDI = "#009900",
            Immunosuppression = "magenta4"
            
          ),
          labels = c(
            "Age group", "Sex", "Ethnicity",
            "Region", "TDI", "I*: Immunosupression"
          ),
          name = "Covariates: "
        ) +
        ggplot2::guides(
          colour = ggplot2::guide_legend(override.aes = list(shape = 16))
        ) +
        ggplot2::labs(
          x = "Odds Ratio (log scale)",
          y = "",
          colour = "Variable"
        ) +
        ggplot2::theme_bw() +
        ggplot2::theme(
          axis.title = element_text(size = 16),
          axis.text = element_text(size = 14),
          legend.title = element_text(size = 16),
          legend.text = element_text(size = 14),
          strip.text = element_text(size = 14),
          axis.text.x = element_text(angle = 45, hjust = 1)
        )
    }
  })
  
  output$linear_regression <- shiny::renderUI({
    x <- getLinearRegressionPlot()
    renderInteractivePlot(x, input$linear_regression_interactive)
  })
  
  output$summarise_linerplot_plot_download <- shiny::downloadHandler(
    filename = "linear_regression.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getLinearRegressionPlot(),
        width = 16,
        height = 9,
        units = "cm",
        dpi = 300
      )
    }
  )
}